// Clean Home: shows only the apps listed in apps.js on a solid background.
// apps.js is generated by `tv_customize.py home` from the TV's app list.
(function () {
  var cfg = window.HOME_CONFIG || { apps: [], theme: {} };
  var root = document.documentElement.style;
  var t = cfg.theme || {};
  if (t.background) root.setProperty("--bg", t.background);
  if (t.text_color) root.setProperty("--text", t.text_color);
  if (t.accent) root.setProperty("--accent", t.accent);
  if (t.columns) root.setProperty("--cols", t.columns);
  document.getElementById("title").textContent = t.title || "Home";

  var grid = document.getElementById("grid");
  var tiles = [];
  var cols = t.columns || 6;
  var focus = 0;

  function launch(id) {
    if (typeof PalmServiceBridge === "undefined") { console.log("launch", id); return; }
    var bridge = new PalmServiceBridge();
    bridge.onservicecallback = function () {};
    bridge.call("luna://com.webos.applicationManager/launch", JSON.stringify({ id: id }));
  }

  function letterTile(tile, name) {
    var d = document.createElement("div");
    d.className = "letter";
    d.textContent = (name || "?").charAt(0).toUpperCase();
    tile.insertBefore(d, tile.firstChild);
  }

  cfg.apps.forEach(function (app, i) {
    var tile = document.createElement("div");
    tile.className = "tile";
    var label = document.createElement("span");
    label.textContent = app.title;
    tile.appendChild(label);
    if (app.icon) {
      var img = document.createElement("img");
      img.src = app.icon;
      img.onerror = function () { img.remove(); letterTile(tile, app.title); };
      tile.insertBefore(img, label);
    } else {
      letterTile(tile, app.title);
    }
    tile.onclick = function () { launch(app.id); };
    tile.onmouseenter = function () { setFocus(i); };   // Magic Remote pointer
    grid.appendChild(tile);
    tiles.push(tile);
  });

  function setFocus(i) {
    if (!tiles.length) return;
    focus = Math.max(0, Math.min(tiles.length - 1, i));
    tiles.forEach(function (el, j) { el.classList.toggle("focus", j === focus); });
    tiles[focus].scrollIntoView({ block: "nearest" });
  }

  document.addEventListener("keydown", function (e) {
    switch (e.keyCode) {
      case 37: setFocus(focus - 1); break;          // left
      case 39: setFocus(focus + 1); break;          // right
      case 38: setFocus(focus - cols); break;       // up
      case 40: setFocus(focus + cols); break;       // down
      case 13: if (tiles[focus]) launch(cfg.apps[focus].id); break;  // OK
      case 461: e.preventDefault(); break;          // Back: stay on this screen
      default: return;
    }
    e.preventDefault();
  });
  setFocus(0);

  var clock = document.getElementById("clock");
  function tick() {
    if (t.show_clock === false) { clock.textContent = ""; return; }
    var d = new Date();
    clock.textContent = ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2);
  }
  tick(); setInterval(tick, 10000);
})();
